	protected CreateExposureCommand generateNewCommand() {
    CreateExposureCommand command = new CreateExposureCommand( null,  ExposureType.values()[0],  ExposureStatus.values()[0] );

    return( command );
}

    /**
     * Returns a new populated Exposure
     *
     * @return UpdateExposureCommand alias
     */
	protected UpdateExposureCommand generateUpdateCommand() {
    UpdateExposureCommand command = new UpdateExposureCommand( null,  null,  null,  null,  new HashSet<>(),  new HashSet<>(),  ExposureType.values()[0],  ExposureStatus.values()[0] );

    return( command );
}
